import re

_UNITS = {
    'seconds': 1, 'second': 1, 'secs': 1, 'sec': 1, 's': 1,
    'minutes': 60, 'minute': 60, 'mins': 60, 'min': 60, 'm': 60,
    'hours': 3600, 'hour': 3600, 'hrs': 3600, 'hr': 3600, 'h': 3600,
    'days': 86400, 'day': 86400, 'd': 86400,
    'weeks': 604800, 'week': 604800, 'wks': 604800, 'wk': 604800, 'w': 604800,
}

_NUM = r'(?:\d+(?:\.\d*)?|\.\d+)'
_COMPONENT = re.compile(r'\s*(' + _NUM + r')\s*([A-Za-z]+)')
_ISO = re.compile(
    r'P(?:(' + _NUM + r')W)?(?:(' + _NUM + r')D)?'
    r'(?:T(?:(' + _NUM + r')H)?(?:(' + _NUM + r')M)?(?:(' + _NUM + r')S)?)?',
    re.IGNORECASE,
)
_ISO_WEIGHTS = (604800, 86400, 3600, 60, 1)


def _to_seconds(total: float) -> int:
    return int(round(total))


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    if s.isdigit():
        return int(s)

    if s.upper().startswith('P'):
        if len(s) == 1 or s[-1].upper() == 'T':
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        m = _ISO.fullmatch(s.upper())
        if not m:
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        total = 0.0
        for group, weight in zip(m.groups(), _ISO_WEIGHTS):
            if group is not None:
                total += float(group) * weight
        return _to_seconds(total)

    if ':' in s:
        parts = [p.strip() for p in s.split(':')]
        if len(parts) not in (2, 3):
            raise ValueError(f"invalid clock duration: {text!r}")
        if not all(re.fullmatch(_NUM, p) for p in parts):
            raise ValueError(f"invalid clock duration: {text!r}")
        values = [float(p) for p in parts]
        total = 0.0
        for v, weight in zip(values, reversed(_ISO_WEIGHTS[-len(values):])):
            total += v * weight
        return _to_seconds(total)

    pos = 0
    total = 0.0
    found = False
    while pos < len(s):
        m = _COMPONENT.match(s, pos)
        if not m:
            raise ValueError(f"invalid duration: {text!r}")
        unit = m.group(2).lower()
        if unit not in _UNITS:
            raise ValueError(f"unknown unit {m.group(2)!r} in {text!r}")
        total += float(m.group(1)) * _UNITS[unit]
        found = True
        pos = m.end()
        while pos < len(s) and s[pos].isspace():
            pos += 1
    if not found:
        raise ValueError(f"invalid duration: {text!r}")
    return _to_seconds(total)

